def parse_q(s):
    """'YYYYMMDD:VAL|...' -> {iso_date: usd_millions}"""
    out = {}
    for part in (s or "").split("|"):
        if not part:
            continue
        d, v = part.split(":")
        out[f"{d[0:4]}-{d[4:6]}-{d[6:8]}"] = float(v)
    return out


def parse_ytd(s):
    """'YYMMDD_YYMMDD:VAL|...' -> [(fy_start_iso, end_iso, usd_millions)]"""
    rows = []
    for part in (s or "").split("|"):
        if not part:
            continue
        k, v = part.split(":")
        a, b = k.split("_")
        def iso(x):
            y = int(x[0:2])
            year = 2000 + y if y < 70 else 1900 + y
            return f"{year}-{x[2:4]}-{x[4:6]}"
        rows.append((iso(a), iso(b), float(v)))
    return rows
